// Session09ParameterDemo.cs
// Lab 1 of 4 - Observe an Ordinary Value Parameter
public class Session09ParameterDemo
{
    public void Run()
    {
        int originalValue = 10;
        ChangeCopy(originalValue);
        Console.WriteLine($"Caller after ordinary call: {originalValue}");
    }

    public void ChangeCopy(int value)
    {
        value = 99;
        Console.WriteLine($"Inside ordinary method: {value}");
    }
}

// Append to Program.cs
var session09 = new Session09ParameterDemo();
session09.Run();

// Add inside Run.
bool parsedSuccessfully = TryParseHours("8.5", out decimal parsedHours);
Console.WriteLine($"Parsed successfully: {parsedSuccessfully}");
Console.WriteLine($"Parsed hours: {parsedHours:F2}");

// Add below ChangeCopy.
public bool TryParseHours(string text, out decimal hours)
{
    return decimal.TryParse(text, out hours);
}

// Add inside Run.
int counter = 1;
Increment(ref counter);
Console.WriteLine($"Counter after ref call: {counter}");

// Add below TryParseHours.
public void Increment(ref int value)
{
    value++;
}

// Add inside Run.
decimal measurement = 12.5m;
DisplayMeasurement(in measurement);

// Add below Increment.
public void DisplayMeasurement(in decimal measurement)
{
    Console.WriteLine($"Measurement through in: {measurement:F2}");
    // measurement = 99m; // Does not compile: the in parameter is readonly.
}
